#!/usr/bin/env python3
"""Reuse original C4 factories, validation and commands; strip toolkit lifetime only."""
import argparse,hashlib,json,subprocess,re
from pathlib import Path
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--check',action='store_true');p.add_argument('--extractor',type=Path,default=HERE/'FormSourceGen/bin/Release/net10.0/FormSourceGen.dll');a=p.parse_args()
forms={f['name']:f for f in json.loads(subprocess.check_output(['dotnet',str(a.extractor),str(ROOT)],text=True))}
def method(n,m):return next(v['code'] for v in forms[n]['methods'] if v['name']==m)
def prop(n,m):return next(v['code'] for v in forms[n]['properties'] if v['name']==m)
def clean(s):
 s=s.replace('propertyGrid.SelectedObject','SelectedObject').replace('lvTypes.Items','choices').replace('ListViewItem','EditorChoice')
 for t in ['ItemSetDataEditor.SelectionForm.Hide();','propertyGrid.Refresh();','HighlightHistoryOutput();','ShowHideSelectionForm();','_controller.ClearAllSelection();']:
  s=s.replace(t,'; /* Toolkit presentation. */')
 s=s.replace('UserControls.FrmProperties.CheckName','CheckName')
 return s
out=['''// Generated by X/UI/generate-results-forms.py; do not edit.
// Original PrePoMax Copyright (C) 2016-2026 Matej Borovinšek; root LICENSE.
using System;using System.Collections.Generic;using System.Linq;
using CaeGlobals;using CaeMesh;using CaeModel;using CaeResults;using CaeJob;using PrePoMax;using PrePoMax.Forms;
namespace PrePoMaxX.UI.OriginalForms;
''']
def add(n,fields,ctor,members,item,select):
 out.append('// Source '+forms[n]['file']+' SHA256 '+hashlib.sha256((ROOT/forms[n]['file']).read_text(encoding='utf-8-sig').encode()).hexdigest()+'\npublic sealed class '+n+'Rule : ResultFormRule {\n'+fields+'\npublic '+n+'Rule(Controller controller,string name=null):base(controller,name){'+ctor+'}\n'+members+'\npublic override object Item=>'+item+';\nprotected override void OnSelect(object value){'+select+'}\n}\n')
n='FrmAnalysis'
apply=method(n,'btnOK_Click');body=next(v['tryBody'] for v in forms[n]['methods'] if v['name']=='btnOK_Click').replace('Hide();','')
add(n,'string[] _jobNames;string _jobToEditName;ViewAnalysisJob _viewJob;', '''_jobNames=controller.GetJobNames();_jobToEditName=name;
Job=name==null?new AnalysisJob(GetJobName(),controller.Settings.Solver.CalculixExe,GetJobName(),controller.Settings.GetWorkDirectory()):controller.GetJob(name);
_viewJob.PopulateSolverSettings(new[]{FEMSolverEnum.Calculix,FEMSolverEnum.Abaqus,FEMSolverEnum.FEMaster},new[]{controller.Settings.Solver.CalculixExe,controller.Settings.Solver.AbaqusExe,controller.Settings.Solver.FEMasterExe},new[]{controller.Settings.GetWorkDirectory(),controller.Settings.GetWorkDirectory(),controller.Settings.GetWorkDirectory()});SelectedObject=_viewJob;''',clean(prop(n,'Job')+method(n,'GetJobName')+'protected override void OnApply(bool addNew)'+body),'Job','')
n='FrmResultFieldOutput'
add(n,'string[] _resultFieldOutputNames;string _resultFieldOutputToEditName;ViewResultFieldOutput _viewResultFieldOutput;', '''_resultFieldOutputNames=controller.GetResultFieldOutputNames();_resultFieldOutputToEditName=name;
var fields=controller.CurrentResult.GetAllVisibleFiledNameComponentNames();if(name!=null)fields.Remove(name);
PopulateListOfResultFieldOutputs(fields,controller.GetResultPartNames(),controller.GetResultUserElementSetNames(),controller.GetResultCoordinateSystemNames());
if(name==null)Select(0);else{ResultFieldOutput=controller.GetResultFieldOutput(name);SelectedObject=_viewResultFieldOutput;_propertyItemChanged=!ResultFieldOutput.Valid;
if(_viewResultFieldOutput is ViewResultFieldOutputLimit limit)limit.PopulateDropDownLists(fields);
else if(_viewResultFieldOutput is ViewResultFieldOutputEnvelope envelope)envelope.PopulateDropDownLists(fields);
else if(_viewResultFieldOutput is ViewResultFieldOutputCoordinateSystemTransform transform)transform.PopulateDropDownLists(fields,controller.GetResultCoordinateSystemNames());}''',clean(prop(n,'ResultFieldOutput')+'\n'+method(n,'PopulateListOfResultFieldOutputs')+'\n'+method(n,'GetResultFieldOutputName')+'\n'+method(n,'GetShellSourceFieldNames')+'\n'+method(n,'GetPreferredShellFieldName')+'\n'+method(n,'OnApply')),'ResultFieldOutput','if(value is ViewResultFieldOutput view)_viewResultFieldOutput=view;')
n='FrmResultHistoryOutput'
helpers=['PopulateListOfHistoryOutputs','GetAvailableHistorySources','GetMergeFirstSources','GetCompatibleMergeSources','ContainsSource','GetEntryNamesBySource','GetXYXSources','GetHistorySourceNames','GetHistorySourceName','CheckChangedHistorySources','GetHistoryOutputTypeIndex','GetHistoryOutputName']
members=prop(n,'ResultHistoryOutput')+'\n'+'\n'.join(method(n,m) for m in helpers)+'\n'+'\n'.join(m['code'] for m in forms[n]['methods'] if m['name']=='PopulateDropDownLists')+'\n'+method(n,'OnApply')
# Data comes directly from the original table object's Data, rather than a DataGridView copy.
members=members.replace('UpdateTableDataFromGrid(true);','((ResultHistoryOutputFromTable)ResultHistoryOutput).CheckData();')
members+='''
protected override void PropertyChanged(string property) {
 base.PropertyChanged(property);
 if(_viewResultHistoryOutput is ViewResultHistoryOutputFromMergedHistories merged)PopulateDropDownLists(merged);
 else if(_viewResultHistoryOutput is ViewResultHistoryOutputFromIntegration integral && property==nameof(integral.IntegralType)){integral.RegionType=RegionTypeEnum.Selection.ToString();_controller.ClearAllSelection();}
}
public override string[] SelectionPrefixes=>ResultHistoryOutput is ResultHistoryOutputFromField or ResultHistoryOutputFromIntegration?[""]:[];
public override vtkSelectItem SelectionKind=>ResultHistoryOutput is ResultHistoryOutputFromField?vtkSelectItem.Node:
 ResultHistoryOutput is ResultHistoryOutputFromIntegration integration && integration.IntegralType==IntegralTypeEnum.Line?vtkSelectItem.GeometryEdge:ResultHistoryOutput is ResultHistoryOutputFromIntegration volume && volume.IntegralType==IntegralTypeEnum.Volume?vtkSelectItem.Element:vtkSelectItem.Surface;
'''
add(n,'string[] _resultHistoryOutputSetNames;string _resultHistoryOutputToEditName;ViewResultHistoryOutput _viewResultHistoryOutput;', '''_resultHistoryOutputSetNames=controller.GetHistoryResultSetNames();_resultHistoryOutputToEditName=name;
PopulateListOfHistoryOutputs(controller.GetResultUserNodeSetNames(),controller.GetResultUserElementSetNames(),controller.GetResultUserSurfaceNames(),controller.CurrentResult.GetAllVisibleFiledNameComponentNames(),controller.CurrentResult.GetAllExistingIncrementIds());
if(name==null)Select(0);else{ResultHistoryOutput=controller.GetResultHistoryOutput(name);SelectedObject=_viewResultHistoryOutput;_propertyItemChanged=!ResultHistoryOutput.Valid;
var fields=controller.CurrentResult.GetAllVisibleFiledNameComponentNames();
if(_viewResultHistoryOutput is ViewResultHistoryOutputFromField field)field.PopulateDropDownLists(controller.GetResultUserNodeSetNames(),controller.GetResultUserSurfaceNames(),fields,controller.CurrentResult.GetAllExistingIncrementIds());
else if(_viewResultHistoryOutput is ViewResultHistoryOutputFromIntegration integral){integral.SetDefaultCrossSection(controller.GetDefaultResultIntegrationCrossSection());integral.PopulateDropDownLists(controller.GetResultUserElementSetNames(),controller.GetResultUserSurfaceNames(),fields);}
else if(_viewResultHistoryOutput is ViewResultHistoryOutputFromMergedHistories merged)PopulateDropDownLists(merged);
else if(_viewResultHistoryOutput is ViewResultHistoryOutputFromExtractedEntry extracted)PopulateDropDownLists(extracted);
else if(_viewResultHistoryOutput is ViewResultHistoryOutputXY xy)PopulateDropDownLists(xy);
else SelectedObject.GetType().GetMethod("PopulateDropDownLists",Type.EmptyTypes)?.Invoke(SelectedObject,null);}''',clean(members),'ResultHistoryOutput','if(value is ViewResultHistoryOutput view)_viewResultHistoryOutput=view;')
# The C2 reference/coordinate rules already retain the original view-sensitive
# apply methods. Reuse those reviewed full members with result-scoped preparation.
shared=(HERE/'Workbench/OriginalFormRules.g.cs').read_text()
for original,new in [('FrmReferencePointRule','ResultReferencePointRule'),('FrmCoordinateSystemRule','ResultCoordinateSystemRule')]:
 start=shared.index('public sealed class '+original+' : FormRule {')
 end=shared.index('\n}\n',start)+3
 code=shared[start:end].replace(original,new).replace(': FormRule {',': ResultFormRule {')
 code=code.replace('(Controller controller,string step,string name) : base(controller,step,name)','(Controller controller,string name=null) : base(controller,name)')
 for old,value in [('GetModelReferencePoint','GetResultReferencePoint'),('GetModelCoordinateSystem','GetResultCoordinateSystem'),('GetUserNodeSetNames','GetResultUserNodeSetNames'),('GetUserSurfaceNames','GetResultUserSurfaceNames')]:code=code.replace(old,value)
 # Retain the original form's Model.Properties.ModelSpace.IsTwoD() choice.
 code=code.replace('_controller.GetAllMeshEntityNames()','_controller.GetResultCoordinateSystemNames()' if 'Coordinate' in new else '_controller.GetResultReferencePointNames()')
 if 'Coordinate' in new:code=code.replace('Configure(_viewCoordinateSystem); choices.Add','CoordinateSystem.Color=_controller.Settings.Pre.ConstraintSymbolColor; Configure(_viewCoordinateSystem); choices.Add')
 else:
  code=code.replace('new FeReferencePoint(GetReferencePointName(),0,0,0)','(_controller.Model.Properties.ModelSpace.IsTwoD()?new FeReferencePoint(GetReferencePointName(),0,0):new FeReferencePoint(GetReferencePointName(),0,0,0))')
  code=code.replace('Configure(_viewReferencePoint); choices.Add','ReferencePoint.Color=_controller.Settings.Pre.ConstraintSymbolColor; Configure(_viewReferencePoint); choices.Add')
 code=code.rstrip()[:-1]+'public override vtkSelectItem SelectionKind=>vtkSelectItem.Node;\npublic override string[] SelectionPrefixes=>'+('["Center","PointX","PointXY"]' if 'Coordinate' in new else '[""]')+';\n}\n'
 out.append('// Reused C2 rule '+original+'; results-scoped preparation; shared source SHA256 '+hashlib.sha256(shared.encode()).hexdigest()+'\n'+code)
n='FrmTransformation'
code=clean(method(n,'ApplyTransformation')).replace('lvActiveTransformations.Items','active')
out.append('// Source '+forms[n]['file']+' SHA256 '+hashlib.sha256((ROOT/forms[n]['file']).read_text(encoding='utf-8-sig').encode()).hexdigest()+"""
public sealed class TransformationEditSession(Controller controller) {
 readonly Controller _controller=controller;bool _propertyItemChanged;
 readonly List<EditorChoice> active=(controller.GetTransformations()??[]).DeepClone().Select(t=>new EditorChoice(t.Name){Tag=Wrap(t)}).ToList();
 public int Count=>active.Count;
 public string Name(int index)=>((ViewTransformation)active[index].Tag).Base.Name;
 static ViewTransformation Wrap(Transformation item)=>item switch{Symmetry sym=>new ViewSymmetry(sym),LinearPattern line=>new ViewLinearPattern(line),CircularPattern circle=>new ViewCircularPattern(circle),_=>throw new NotSupportedException()};
 public PropertySheet Properties(int index)=>new(active[index].Tag,changed:()=>_propertyItemChanged=true);
 public void Add(int type){Transformation item=type switch{0=>new Symmetry("Symmetry-X",new double[3],SymmetryPlaneEnum.X),1=>new Symmetry("Symmetry-Y",new double[3],SymmetryPlaneEnum.Y),2=>new Symmetry("Symmetry-Z",new double[3],SymmetryPlaneEnum.Z),3=>new LinearPattern("Linear",new double[3],new double[]{1,0,0},2),4=>new CircularPattern("Circular",new double[3],new double[]{0,1,0},2,45),_=>throw new ArgumentOutOfRangeException(nameof(type))};active.Add(new EditorChoice(item.Name){Tag=Wrap(item)});_propertyItemChanged=true;}
 public void Remove(int index){active.RemoveAt(index);_propertyItemChanged=true;}
 public void Move(int index,int delta){int target=index+delta;if(target<0||target>=Count)return;var item=active[index];active.RemoveAt(index);active.Insert(target,item);_propertyItemChanged=true;}
"""+code+"}\n")
text='\n'.join(line.rstrip() for line in '\n'.join(out).splitlines())+'\n';path=HERE/'Workbench/OriginalResultsRules.g.cs'
if a.check:
 if not path.exists() or path.read_text()!=text:raise SystemExit('Original C4 rules are stale; regenerate and review.')
else:path.write_text(text)
